@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_update_attributes_is_packet_29(version):
    assert version.PACKETS[29] is version.UpdateAttributesPacket


GOLDENS = [
    pytest.param(PACKET, UPDATE_ATTRIBUTES, id="two-attributes"),
    pytest.param(v2225.UpdateAttributesPacket(runtime_id=0, tick=300), EMPTY, id="empty"),
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_update_attributes_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_update_attributes_decodes_from_its_golden(packet, golden):
    assert v2225.UpdateAttributesPacket.from_bytes(golden) == packet


def test_the_operation_and_operand_sentinels_round_trip():
    packet = v2225.UpdateAttributesPacket(
        attribute_data=[
            v2225.AttributeData(
                modifiers=[
                    v2225.AttributeModifier(
                        operation=v2225.AttributeModifierOperation.OPERATION_INVALID,
                        operand=v2225.AttributeOperands.OPERAND_INVALID,
                        serialize=False,
                    )
                ]
            )
        ]
    )
    assert v2225.UpdateAttributesPacket.from_bytes(bytes(packet)) == packet


def test_the_operation_sentinel_decodes_as_the_total_member():
    packet = v2225.UpdateAttributesPacket(
        attribute_data=[
            v2225.AttributeData(
                modifiers=[v2225.AttributeModifier(operation=v2225.AttributeModifierOperation.OPERATION_INVALID)]
            )
        ]
    )
    back = v2225.UpdateAttributesPacket.from_bytes(bytes(packet))
    assert back.attribute_data[0].modifiers[0].operation is v2225.AttributeModifierOperation.TOTAL_OPERATIONS


def test_the_operand_sentinel_decodes_as_the_total_member():
    packet = v2225.UpdateAttributesPacket(
        attribute_data=[
            v2225.AttributeData(modifiers=[v2225.AttributeModifier(operand=v2225.AttributeOperands.OPERAND_INVALID)])
        ]
    )
    back = v2225.UpdateAttributesPacket.from_bytes(bytes(packet))
    assert back.attribute_data[0].modifiers[0].operand is v2225.AttributeOperands.TOTAL_OPERANDS
